ControlPropertyState.AutoRuleBindingString:
Set(varDrawerTab, "Overview");

Set(
    varCT_HasValues,
    CountRows(
        Filter(
            colCT_Merged_UI,
            !IsBlank(ValueText) ||
            !IsBlank(ValueNumber) ||
            !IsBlank(ValueDate) ||
            ValueBool = true ||
            !IsBlank(ValueJson)
        )
    ) > 0
);

Set(varCT_ShowManageFields, false);
Set(varShowCustomAddFields, false);
Set(varCT_IsDirty, false);
Set(varCT_IsLoading, false);
Set(varCT_IsSaving, false);


// 0) Abrir drawer (UI) y preparar estado base
Set(varShowDetailDrawer, true);
Set(varDrawerIsLoading, true);

// Tabs / paginación (una sola vez)
Set(varDrawerTab, "Overview");
Set(tablistSelected, 1);

Set(varCommentsPageSize, 20);
Set(varCommentsPage, 1);

// 1) Contexto del drawer (identidad del registro)
Set(varDrawerProjectId, varProjectId);
Set(varDrawerEntityType, "TASK");
Set(varDrawerRecordId, ThisItem.InspectionTaskId);

// Guardar el record “crudo” por si lo necesitas para otras cosas
Set(varDrawerSelectedRecord, ThisItem);

// 2) NORMALIZACIÓN (esto es la clave)
// Record común para Overview (y para lo que quieras estandarizar)
Set(
    varDrawerNormalized,
    {
        EntityType: "TASK",
        ProjectId: varProjectId,
        RecordId: ThisItem.InspectionTaskId,

        // WBS
        AreaCode: Coalesce(Text(ThisItem.AreaCode), ""),
        UnitCode: Coalesce(Text(ThisItem.UnitCode), ""),
        SystemCode: Coalesce(Text(ThisItem.SystemCode), ""),
        SubsystemCode: Coalesce(Text(ThisItem.SubsystemCode), ""),
        ElementCode: Coalesce(Text(ThisItem.ElementCode), ""),
        TypeCode: Coalesce(Text(ThisItem.TypeCode), ""),

        // Slots + etiquetas
        TitleLabel: "Form:",
        TitleValue: Coalesce(Text(ThisItem.FormName), "-"),

        DescLabel: "Form Description:",
        DescValue: Coalesce(Text(ThisItem.FormDescription), "-"),

        StatusLabel: "Task Status:",
        StatusValue: Coalesce(Text(ThisItem.TaskStatus), "-"),

        DisciplineLabel: "Element Discipline:",
        DisciplineValue: Coalesce(Text(ThisItem.ElementDiscipline), "-"),

        SecondaryLabel: "Sct:",
        SecondaryValue: Coalesce(Text(ThisItem.Sct), "")
    }
);

// 3) Limpieza de estados dependientes (Custom/Comments/etc.)
// (evita mezcla entre registros cuando cambias de fila)
Set(varCT_LoadKey, ""); // fuerza reload del bundle custom
Clear(colCT_Merged);
Clear(colCT_Quick);
Clear(colCT_Dirty);

// 4) Reset del componente (solo si de verdad lo necesitas)
// Si tu diseño depende de OnReset para reenganchar cosas, mantenlo.
// Si no, esto es ruido y deberías eliminarlo.
Reset(comp_DetailDrawer);

// 5) Disparar carga del drawer
// Mantén un único disparador. Si ya tienes btnDrawerLoad como “motor”, úsalo.
Select(btnDrawerLoad);

Switch(
    Coalesce(varTasks_ReturnView, "Overview"),

    "Home",
        Set(varAppView, "Home");
        Set(varHomeViewMode, "DASHBOARD"),

    "Overview",
        Set(varAppView, "Overview");
        Set(varOps_ViewMode, "OVERVIEW"),

    Set(varAppView, "Overview");
    Set(varOps_ViewMode, "OVERVIEW")
)

Set(varCT_DefsIsLoading, true);
Set(varCT_DefsError, "");

Clear(colCT_Defs_Admin);

Set(
    varCT_DefsResp,
    WarRoom_ListCustomFieldDefs.Run(
        comp_DetailDrawer_1.ProjectId,
        comp_DetailDrawer_1.EntityType,
        If(varCT_ShowInactiveDefs, 1, 0)
    )
);


Set(
    varCT_DefsOuter,
    Table(ParseJSON(Coalesce(varCT_DefsResp.result, "[]")))
);

If(
    CountRows(varCT_DefsOuter) = 0,

    Set(varCT_DefsError, "The flow returned no data."),

    Set(
        varCT_DefsBundle,
        ParseJSON(
            Text(First(varCT_DefsOuter).Value.result)
        )
    );

    ClearCollect(
        colCT_Defs_Admin,
        ForAll(
            Table(varCT_DefsBundle.defs),
            {
                FieldDefId: Value(ThisRecord.Value.FieldDefId),
                ProjectId: Value(ThisRecord.Value.ProjectId),
                EntityType: Text(ThisRecord.Value.EntityType),
                FieldKey: Text(ThisRecord.Value.FieldKey),
                Label: Text(ThisRecord.Value.Label),
                FieldType: Text(ThisRecord.Value.FieldType),
                HelpText: Coalesce(Text(ThisRecord.Value.HelpText), ""),
                IsRequired: Boolean(ThisRecord.Value.IsRequired),
                IsPinned: Boolean(ThisRecord.Value.IsPinned),
                IsActive: Boolean(ThisRecord.Value.IsActive),
                SortOrder: Value(ThisRecord.Value.SortOrder),
                OptionsJson: Coalesce(Text(ThisRecord.Value.OptionsJson), ""),
                ModifiedOn: If(
                    IsBlank(Text(ThisRecord.Value.ModifiedOn)),
                    Blank(),
                    DateTimeValue(Text(ThisRecord.Value.ModifiedOn))
                ),
                ModifiedByEmail: Coalesce(Text(ThisRecord.Value.ModifiedByEmail), "")
            }
        )
    )
);

Set(varCT_DefsIsLoading, false);

Set(varIsLoadingComments, true);

Set(varCommentsPage, 1);
Set(varCommentsPageSize, Coalesce(varCommentsPageSize, 20));

With(
    {
        resp: Warroom_GetTaskCommentsPaged.Run(
            varProjectId,
            varDrawerRecordId,
            varCommentsPage,
            varCommentsPageSize,
            varDrawerEntityType
        )
    },
    With(
        {
            arr: Table(ParseJSON(Coalesce(resp.result, "[]")))
        },
        ClearCollect(
            colComments,
            ForAll(
                arr,
                {
                    CommentId: Value(ThisRecord.Value.CommentId),
                    CommentText: Text(ThisRecord.Value.CommentText),
                    CommentType: Text(ThisRecord.Value.CommentType),
                    CreatedOn: DateTimeValue(Text(ThisRecord.Value.CreatedOn)),
                    CreatedByEmail: Text(ThisRecord.Value.CreatedByEmail),
                    CreatedByName: Text(ThisRecord.Value.CreatedByName),
                    TotalRows: Value(ThisRecord.Value.TotalRows),
                    TotalPages: Value(ThisRecord.Value.TotalPages),
                    PageNumber: Value(ThisRecord.Value.PageNumber),
                    PageSize: Value(ThisRecord.Value.PageSize)
                }
            )
        )
    )
);

Set(varCommentsTotalRows, If(CountRows(colComments) > 0, First(colComments).TotalRows, 0));
Set(varCommentsTotalPages, If(CountRows(colComments) > 0, First(colComments).TotalPages, 0));

Set(varIsLoadingComments, false);
Set(varDrawerIsLoading, false);

Set(varCT_Loading, true);
Set(varCT_Error, "");

// Limpieza
Clear(colCT_Quick);
Clear(colCT_Merged_Base);
Clear(colCT_Merged_UI);

// Llamada al flow
With(
    {
        resp: WarRoom_GetCustomBundle.Run(
            comp_DetailDrawer_1.ProjectId,
            comp_DetailDrawer_1.EntityType,
            comp_DetailDrawer_1.RecordId
        )
    },

    With(
        {
            parsed: ParseJSON(Coalesce(resp.bundlejson, "{}"))
        },

        // Base (defs)
        ClearCollect(
            colCT_Merged_Base,
            ForAll(
                Table(parsed.defs),
                {
                    FieldKey: Text(ThisRecord.Value.FieldKey),
                    Label: Text(ThisRecord.Value.Label),
                    FieldType: Text(ThisRecord.Value.FieldType),
                    IsRequired: Boolean(ThisRecord.Value.IsRequired),
                    IsPinned: Boolean(ThisRecord.Value.IsPinned),
                    SortOrder: Value(ThisRecord.Value.SortOrder),
                    OptionsJson: Text(ThisRecord.Value.OptionsJson)
                }
            )
        );

        // Valores (values)
        ClearCollect(
            colCT_Merged_UI,
            ForAll(
                Table(parsed.values),
                {
                    FieldKey: Text(ThisRecord.Value.FieldKey),
                    ValueText: Text(ThisRecord.Value.ValueText),
                    ValueNumber: Value(ThisRecord.Value.ValueNumber),
                    ValueDate: If(
                        !IsBlank(ThisRecord.Value.ValueDate),
                        DateTimeValue(Text(ThisRecord.Value.ValueDate)),
                        Blank()
                    ),
                    ValueBool: Boolean(ThisRecord.Value.ValueBool)
                }
            )
        )
    )
);

// Merge final (lo que pinta la UI)
ClearCollect(
    colCT_Quick,
    AddColumns(
        colCT_Merged_Base,
        CurrentValue,
        LookUp(colCT_Merged_UI, FieldKey = ThisRecord.FieldKey)
    )
);

Set(varCT_Loading, false);

Set(varDrawerIsLoading, true);

Switch(
    varDrawerTab,
    "Comments", Select(btnDrawerLoad_Comments_1),
    "Custom", Select(btnDrawerLoad_Custom_1),
    "Overview", Set(varDrawerIsLoading, false),
    "History", Set(varDrawerIsLoading, false),
    Set(varDrawerIsLoading, false)
);

With(
    {
        _key: Lower(Trim(cmp_NavApp_Tasks.SelectedItemKey)),
        _hasProject: !IsBlank(varProjectId)
    },
    If(
        _key <> "home" && !_hasProject,

        Notify("Please select a project first.", NotificationType.Warning);
        Set(varAppView, "Home");
        Navigate(scr_Home, ScreenTransition.None),

        Switch(
            _key,

            "home",
                Set(varAppView, "Home");
                Navigate(scr_Home, ScreenTransition.None),

            "overview",
                Set(varAppView, "Overview");
                Set(varOps_ViewMode, "OVERVIEW");
                Navigate(scr_Overview, ScreenTransition.None),

            "tasks",
                Set(varAppView, "Tasks");
                Navigate(scr_Tasks, ScreenTransition.None),

            "punches",
                Set(varAppView, "Punches");
                Navigate(scr_Punches, ScreenTransition.None),

            "briefing",
                Set(varAppView, "Briefing");
                Navigate(scr_Briefing, ScreenTransition.None),

            "config",
                Set(varAppView, "Config");
                Navigate(scr_Config, ScreenTransition.None),

            "superadmin",
                Set(varAppView, "SuperAdmin");
                Navigate(scr_SuperAdmin, ScreenTransition.None),

            Notify("Key not mapped: [" & _key & "]", NotificationType.Error)
        )
    )
)
